const mode=$('Prep').first().json.mode;
const vr=($input.first().json.valueRanges||[]);
const pick=n=>{const m=vr.find(x=>String(x.range||'').replace(/'/g,'').toUpperCase().startsWith(n+'!'));return (m&&m.values)?m.values:[];};
const ONB=pick('ONBOARDING'),INV=pick('INVESTORS'),BNC=pick('BOUNCES'),STA=pick('STARTUPS');
const s=v=>String(v==null?'':v).trim();
if(mode==='headers'){
  return [{json:{onb_rows:ONB.length,inv_rows:INV.length,bnc_rows:BNC.length,sta_rows:STA.length,
    onb_header:(ONB[0]||[]).map((h,i)=>i+':'+s(h)),
    inv_header:(INV[0]||[]).map((h,i)=>i+':'+s(h)),
    bnc_header:(BNC[0]||[]).map((h,i)=>i+':'+s(h)),
    sta_header:(STA[0]||[]).map((h,i)=>i+':'+s(h)),
    onb_sample:(ONB[1]||[]).map((h,i)=>i+':'+s(h)).filter(x=>!/^\d+:$/.test(x))}}];
}
if(mode==='onb'){
  const out=[];
  for(let i=1;i<ONB.length;i++){const r=ONB[i]||[];if(!s(r[5])&&!s(r[8])){continue;}
    out.push({row:i+1,status:s(r[4]),firm:s(r[5]),contact:s(r[6]),email:s(r[8]),sector:s(r[19]),subject:s(r[24]),sent_date:s(r[27]),thread_id:s(r[28]),reply:s(r[29]),outcome:s(r[36]),fu1:s(r[38]),fu1d:s(r[39]),fu2:s(r[40]),fu2d:s(r[41])});}
  return [{json:{count:out.length,rows:out}}];
}
if(mode==='ref'){
  const ih=(INV[0]||[]).map(h=>s(h).toLowerCase());
  const iName=ih.findIndex(h=>/^(firm|investor|investor_name|firm_name|name)$/.test(h));
  const iDnc=ih.findIndex(h=>/do_not_contact|dnc/.test(h));
  const dnc=[];
  if(iName>=0&&iDnc>=0){for(let i=1;i<INV.length;i++){const r=INV[i]||[];const v=s(r[iDnc]).toLowerCase();if(v&&v!=='false'&&v!=='no'&&v!=='0'){dnc.push({firm:s(r[iName]),flag:s(r[iDnc])});}}}
  const bh=(BNC[0]||[]).map(h=>s(h).toLowerCase());
  const bEmail=bh.findIndex(h=>/email|address/.test(h));
  const bHard=bh.findIndex(h=>/hard_or_soft|hard/.test(h));
  const bFirm=bh.findIndex(h=>/firm|investor/.test(h));
  const hard=[];
  for(let i=1;i<BNC.length;i++){const r=BNC[i]||[];if(bHard>=0&&/^hard$/i.test(s(r[bHard]))){hard.push({email:bEmail>=0?s(r[bEmail]).toLowerCase():'',firm:bFirm>=0?s(r[bFirm]):''});}}
  return [{json:{inv_name_col:iName,inv_dnc_col:iDnc,dnc_count:dnc.length,dnc:dnc,bnc_email_col:bEmail,bnc_hard_col:bHard,hard_count:hard.length,hard:hard}}];
}
if(mode==='startups'){
  const h=(STA[0]||[]).map((x,i)=>i+':'+s(x));
  const out=[];
  for(let i=1;i<STA.length;i++){const r=STA[i]||[];if(!s(r[0])&&!s(r[1])){continue;}out.push({row:i+1,cells:r.map(c=>s(c))});}
  return [{json:{header:h,count:out.length,rows:out}}];
}
throw new Error('unknown mode '+mode);
